"""Generate vocabulary.json with 500+ technical English terms for Turkish developers."""
import json
import os

vocab = []

def v(term, translation, pronunciation, difficulty, domain, def_en, def_tr, examples, patterns, scenario, mistakes, related):
    vocab.append({
        'term': term, 'translation': translation, 'pronunciation': pronunciation,
        'difficulty_level': difficulty, 'domain': domain,
        'definition_en': def_en, 'definition_tr': def_tr,
        'example_sentences': examples, 'common_patterns': patterns,
        'scenario': scenario, 'common_mistakes': mistakes,
        'related_terms': related, 'lesson_id': None
    })

def ex(en, tr, ctx):
    return {'en': en, 'tr': tr, 'context': ctx}

